argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W32Img {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd,int n);
}
"@
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
[W32Img]::ShowWindow($edge.MainWindowHandle,9)|Out-Null
[W32Img]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$edit=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit){
   $r=$e.Current.BoundingRectangle
   if($r.Y -gt 500 -and $r.Width -gt 300 -and $r.Width -lt 900){ $edit=$e; break }
 }
}
if($null -eq $edit){throw 'Gemini prompt edit not found'}
$edit.SetFocus()
$txt=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Set-Clipboard -Value $txt
Start-Sleep -Milliseconds 250
[System.Windows.Forms.SendKeys]::SendWait('^a')
[System.Windows.Forms.SendKeys]::SendWait('^v')
Start-Sleep -Milliseconds 350
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 24
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 $ct=$e.Current.ControlType.ProgrammaticName
 $name=[string]$e.Current.Name
 if($ct -match 'Button|Image|Text' -and ($name -or $ct -match 'Image')){
   $r=$e.Current.BoundingRectangle
   if($r.Y -gt 250){
     $out += [pscustomobject]@{type=$ct;name=$name;aid=[string]$e.Current.AutomationId;x=[int]$r.X;y=[int]$r.Y;w=[int]$r.Width;h=[int]$r.Height;enabled=[bool]$e.Current.IsEnabled}
     if($out.Count -ge 180){break}
   }
 }
}
[pscustomobject]@{title=$edge.MainWindowTitle;controls=$out}|ConvertTo-Json -Depth 6 -Compress
